-- Issue #740 slice 1: Kindle polling (docs 9.4). Voluntary voter-intent answers (one per citizen per election) and daily published aggregate snapshots, flag HARIMU_KINDLE_POLLING_ENABLED (off in production). Additive only.
CREATE TABLE IF NOT EXISTS kindle_poll_answers (election_id TEXT COLLATE "C" NOT NULL, clerk_user_id TEXT COLLATE "C" NOT NULL REFERENCES citizens(clerk_user_id) ON DELETE CASCADE, candidate_id TEXT COLLATE "C" NOT NULL, answered_at BIGINT NOT NULL, request_id TEXT COLLATE "C" NOT NULL UNIQUE, PRIMARY KEY (election_id, clerk_user_id));
CREATE TABLE IF NOT EXISTS kindle_poll_snapshots (election_id TEXT COLLATE "C" NOT NULL, day BIGINT NOT NULL, n BIGINT NOT NULL CHECK(n >= 10), margin DOUBLE PRECISION NOT NULL, shares_json TEXT COLLATE "C" NOT NULL, published_at BIGINT NOT NULL, PRIMARY KEY (election_id, day));
